CREATE INDEX "task_runs_sleep_check_finished_idx" ON "task_runs" USING btree ("created_at") WHERE "task_runs"."status" IN ('failed', 'canceled', 'completed') AND "task_runs"."machine_id" IS NOT NULL AND "task_runs"."sleep_requested_at" IS NULL AND "task_runs"."snapshot_id" IS NULL AND "task_runs"."snapshot_requested_at" IS NULL AND "task_runs"."vendor" IN ('modal', 'daytona', 'e2b', 'docker', 'blaxel', 'box', 'roomote', 'azure');